{
  "groups": [
    {
      "group_id": "low_rate_lockin_high_impact",
      "rule": "rate_type == 'fixed' and origination_year <= 2021 and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers who secured historic low rates during the pandemic face severe payment shock at renewal and will be highly sensitive to retention offers."
    },
    {
      "group_id": "distressed_variable_rate",
      "rule": "rate_type == 'variable' and credit_score_band in ['600_659', 'below_600']",
      "rationale": "Variable rate borrowers with lower credit scores have already experienced payment increases and possess high risk of default or lender switching."
    },
    {
      "group_id": "overleveraged_families",
      "rule": "n_children >= 2 and household_income_cad < 100000 and credit_utilization_pct > 45",
      "rationale": "Households with multiple children and high debt usage have limited financial flexibility and are susceptible to rising cost of living pressures."
    },
    {
      "group_id": "uninsured_equity_constrained",
      "rule": "insured_flag == False and credit_score_band == '660_719'",
      "rationale": "Uninsured borrowers with moderate credit scores face significant barriers to switching lenders due to strict stress-test qualifications on new applications."
    },
    {
      "group_id": "affluent_rate_shoppers",
      "rule": "credit_score_band == '720_plus' and mortgage_balance_cad > 450000 and has_investments == True",
      "rationale": "High-net-worth borrowers with strong equity positions are prime targets for competitor acquisition and represent the most significant potential loss of assets under management."
    },
    {
      "group_id": "near_term_renewal_at_risk",
      "rule": "term_months <= 36 and life_event_6m == True",
      "rationale": "Borrowers nearing the end of their term who have recently experienced a major life change are likely to re-evaluate their entire financial strategy."
    },
    {
      "group_id": "self_employed_volatility",
      "rule": "employment_status == 'self_employed' and td_deposits_3m_change_cad < 0",
      "rationale": "Self-employed borrowers showing a decline in liquid savings exhibit cash-flow volatility that necessitates proactive outreach to prevent delinquency."
    }
  ]
}
